insert into public.outcomes(id,opportunity_id,title,public_area,completed_at,actions_completed,approved_image,community_message,activity,why_it_matters,demonstration_date,published,sample) values('32fd1366-3570-44db-a674-5147513b9e42','habitat-demo','Creating a safer wildlife route','Local park edge','2026-01-01','Volunteers planted native shrubs and removed rubbish from the habitat area.','illustration:planting','Thank you to the residents who helped care for our shared environment.','Native planting and litter removal','Connected vegetation can provide shelter and safer movement paths for urban wildlife.','Demonstration date · To be confirmed',true,true) on conflict(id) do nothing;
insert into public.outcomes(id,opportunity_id,title,public_area,completed_at,actions_completed,approved_image,community_message,activity,why_it_matters,demonstration_date,published,sample) values('0ec5fd77-db2a-4083-a7ba-648b95c6db96','pond-care-demo','Caring for the park pond','Community park pond','2026-01-01','Volunteers removed litter from the pond surroundings and learned how rubbish can affect birds, frogs and water dragons.','illustration:pond','Small local actions can create a safer shared space for people and wildlife.','Litter collection and habitat-care session','Cleaner pond edges can reduce hazards for animals using the water and surrounding vegetation.','Demonstration date · To be confirmed',true,true) on conflict(id) do nothing;
insert into public.outcomes(id,opportunity_id,title,public_area,completed_at,actions_completed,approved_image,community_message,activity,why_it_matters,demonstration_date,published,sample) values('ccf88ecf-a5a2-4dbb-a037-a9856a172625','garden-care-demo','Restoring native shelter','Community garden boundary','2026-01-01','Volunteers added native vegetation under the guidance of the activity organiser.','illustration:garden','Thank you for helping improve neighbourhood habitat.','Planting locally appropriate shrubs','Shrubs may provide shelter and contribute to connected urban habitat.','Demonstration date · To be confirmed',true,true) on conflict(id) do nothing;
insert into public.outcomes(id,opportunity_id,title,public_area,completed_at,actions_completed,approved_image,community_message,activity,why_it_matters,demonstration_date,published,sample) values('848d3072-b845-4625-afc0-59f03ab770d7','reserve-care-demo','A cleaner reserve entrance','Local reserve entrance','2026-01-01','Volunteers collected litter from paths and vegetation without entering sensitive habitat areas.','illustration:cleanup','The activity combined practical care with learning about local animals.','Supervised park clean-up','Removing rubbish can reduce entanglement and ingestion risks for wildlife.','Demonstration date · To be confirmed',true,true) on conflict(id) do nothing;
